L["wait a moment before thanking: |cff00ff00on|r"] = "esperar un momento antes de dar las gracias: |cff00ff00activado|r"
L["waiting to thank: |cffffffff%s|r"] = "esperando para dar las gracias: |cffffffff%s|r"
